import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.v1TqQkD7.js";const g=JSON.parse('{"title":"Releasing ESI.ts","description":"","frontmatter":{"title":"Releasing ESI.ts","sourceFile":"guides/RELEASE.md"},"headers":[],"relativePath":"guide/release.md","filePath":"guide/release.md"}'),o={name:"guide/release.md"};function n(d,e,r,l,c,h){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="releasing-esits" tabindex="-1">Releasing ESI.ts <a class="header-anchor" href="#releasing-esits" aria-label="Permalink to &quot;Releasing ESI.ts&quot;">​</a></h1><p><strong>Implements:</strong> <code>REL-01</code>, <code>REL-02</code>, <code>REL-03</code>, <code>REL-04</code>, <code>REL-05</code>, <code>DOC-01</code> · requirements stated in <a href="./charter">CHARTER.md</a> Part 8</p><p>How a version of <code>@lgriffin/esi.ts</code> goes from merged commits to a published, signed package. The workflows are the fact: <code>.github/workflows/release-please.yml</code>, <code>.github/workflows/release.yml</code>, <code>release-please-config.json</code> and <code>.release-please-manifest.json</code>. Where this guide and a workflow disagree, the workflow wins and the guide is the bug.</p><p>For what runs at commit, push and PR time, see <a href="./quality-gates">QUALITY-GATES.md</a>. For why the signing and provenance controls exist, see <a href="./security">SECURITY.md</a>.</p><hr><h2 id="the-path-of-a-release" tabindex="-1">The path of a release <a class="header-anchor" href="#the-path-of-a-release" aria-label="Permalink to &quot;The path of a release&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>conventional commits on master</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>release-please.yml ──► release PR (version bump + changelog)</span></span>
<span class="line"><span>        │ merge</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>tag vX.Y.Z + GitHub release published</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>release.yml</span></span>
<span class="line"><span>  validate-release ──┬─► publish-npm            (release event only)</span></span>
<span class="line"><span>                     ├─► publish-github         (release event only)</span></span>
<span class="line"><span>                     ├─► deploy-docs</span></span>
<span class="line"><span>                     └─► create-assets ──► sign-and-publish-assets (release event only)</span></span>
<span class="line"><span>                                                        │</span></span>
<span class="line"><span>                                                 notify-success</span></span></code></pre></div><ol><li><strong>Commits land on <code>master</code></strong> through a pull request. Each commit message follows the conventional-commit format (REL-01). The <code>commit-msg</code> Husky hook runs <code>commitlint</code> against <code>@commitlint/config-conventional</code>.</li><li><strong>release-please runs on every push to <code>master</code>.</strong> It reads the commits since the last release, works out the next version, and opens or updates a release pull request, but only once a <code>feat:</code>, a breaking change (<code>type!:</code> or <code>BREAKING CHANGE:</code>) or a <code>Release-As:</code> footer has landed since the last tag. Fixes, chores and dependency bumps on their own open no release pull request; they wait and ship in the next minor or major (see <a href="#release-cadence">Release cadence</a>). That pull request edits <code>package.json</code>, <code>.release-please-manifest.json</code>, <code>CHANGELOG.md</code> and the extra file <code>src/core/constants.ts</code>.</li><li><strong>Merging the release pull request</strong> makes release-please create the <code>vX.Y.Z</code> tag and the GitHub release.</li><li><strong><code>release.yml</code> runs twice</strong>, once for the tag push (<code>v*.*.*</code>) and once for the <code>release: published</code> event. Both runs validate and build the assets. Only the <code>release</code> run, or a <code>workflow_dispatch</code> run on the tag, publishes packages, deploys the documentation, signs assets and then dispatches <code>post-publish-canary.yml</code>; those jobs are guarded by the event name.</li></ol><h3 id="jobs-in-releaseyml" tabindex="-1">Jobs in <code>release.yml</code> <a class="header-anchor" href="#jobs-in-releaseyml" aria-label="Permalink to &quot;Jobs in \`release.yml\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Job</th><th>Needs</th><th>Runs on</th><th>Does</th></tr></thead><tbody><tr><td><code>validate-release</code></td><td>—</td><td>tag push and release</td><td>The publish gate, below</td></tr><tr><td><code>publish-npm</code></td><td><code>validate-release</code>, <code>consumer-contract</code></td><td>release only</td><td>Re-checks <code>checksums.txt</code>, then <code>npm publish &lt;tarball&gt; --provenance</code> of the tarball <code>create-assets</code> packed, to <code>registry.npmjs.org</code></td></tr><tr><td><code>publish-github</code></td><td><code>validate-release</code>, <code>consumer-contract</code></td><td>release only</td><td>The same tarball, <code>npm publish &lt;tarball&gt; --provenance</code> to <code>npm.pkg.github.com</code></td></tr><tr><td><code>deploy-docs</code></td><td><code>validate-release</code></td><td>release only</td><td>Calls <code>docs-site.yml</code>: <code>npm run docs:site</code> (the VitePress site with TypeDoc under <code>/api/</code>), <code>validate:versions -- --site</code>, then deploys <code>docs-site/.vitepress/dist</code> to the <code>gh-pages</code> branch</td></tr><tr><td><code>create-assets</code></td><td><code>validate-release</code></td><td>tag push and release</td><td><code>npm pack</code> (fails unless exactly one tarball), the CycloneDX SBOM (<code>npm run release:sbom</code>), <code>docs.tar.gz</code> of the API reference, <code>checksums.txt</code> (SHA-256); uploads as artifact</td></tr><tr><td><code>consumer-contract</code></td><td><code>create-assets</code></td><td>tag push and release</td><td>The consumer contract (<code>npm run test:consumer -- --tarball</code>) against the tarball <code>create-assets</code> packed: Node 22 and 24, oldest, repository and latest TypeScript</td></tr><tr><td><code>sign-and-publish-assets</code></td><td><code>create-assets</code>, <code>consumer-contract</code></td><td>release only</td><td>Keyless <code>cosign sign-blob</code> on the tarball, SBOM and docs archive; SLSA build provenance for the same three (<code>actions/attest-build-provenance</code>, checked with <code>gh attestation verify</code>); then <code>gh release upload</code> of all assets plus <code>README.md</code> and <code>LICENSE</code></td></tr><tr><td><code>dispatch-canary</code></td><td><code>publish-npm</code>, <code>sign-and-publish-assets</code></td><td>when <code>publish-npm</code> passed</td><td>Dispatches <code>post-publish-canary.yml</code> on the tag (<code>actions: write</code>)</td></tr><tr><td><code>notify-success</code></td><td>all of the above</td><td>when <code>publish-npm</code> passed</td><td>Log line only</td></tr></tbody></table><p>The workflow holds top-level <code>contents: read</code>. Only <code>publish-npm</code>, <code>publish-github</code> and <code>sign-and-publish-assets</code> receive <code>id-token: write</code>, and signing sits in its own job so that no build step shares a job with the ability to mint an OIDC token.</p><p><code>release.yml</code> also has a <code>workflow_dispatch</code> trigger. Dispatch it on the tag, <code>gh workflow run release.yml --ref vX.Y.Z</code>; <code>validate-release</code> fails on any other ref, and on a tag that does not match <code>package.json</code>. <code>release-please.yml</code> has a manual trigger with a <code>force-release</code> box, for shipping a patch on purpose (below).</p><h3 id="the-release-app-token" tabindex="-1">The release app token <a class="header-anchor" href="#the-release-app-token" aria-label="Permalink to &quot;The release app token&quot;">​</a></h3><p>Events raised with the workflow&#39;s <code>GITHUB_TOKEN</code> start no other workflow. A release PR opened with it waits for someone to approve its CI runs, and the tag and release it creates never start <code>release.yml</code> or <code>post-publish-canary.yml</code>. So <code>release-please.yml</code> runs release-please with a GitHub App installation token when the app is configured:</p><table tabindex="0"><thead><tr><th>Name</th><th>Kind</th><th>Value</th></tr></thead><tbody><tr><td><code>RELEASE_APP_CLIENT_ID</code></td><td>Actions variable</td><td>The app&#39;s Client ID</td></tr><tr><td><code>RELEASE_APP_PRIVATE_KEY</code></td><td>Actions secret</td><td>A private key generated for the app (<code>.pem</code>)</td></tr></tbody></table><p>The app is installed on this repository only, with repository permissions Contents, Pull requests and Issues set to read and write, no webhook, and nothing else. The token step asks for those three permissions only.</p><p>Without both, release-please falls back to <code>GITHUB_TOKEN</code>. Its release PR&#39;s CI then has to be approved in the Actions UI, and the <code>dispatch-release</code> job starts <code>release.yml</code> on the new tag (<code>workflow_dispatch</code> is exempt from the rule), unless a dispatched run for that tag already exists. Either way <code>release.yml</code> dispatches the canary itself once <code>publish-npm</code> has succeeded.</p><p>The same fallback applies when minting fails, for example because the app is not installed on the repository (the token API answers 404) or the key was deleted. The run carries a &quot;Release app token&quot; warning annotation saying so, and the release still goes out.</p><hr><h2 id="release-cadence" tabindex="-1">Release cadence <a class="header-anchor" href="#release-cadence" aria-label="Permalink to &quot;Release cadence&quot;">​</a></h2><p>Releases are cut for new features and breaking changes only. A gate step in <code>release-please.yml</code> scans the commits since the last <code>vX.Y.Z</code> tag and skips release-please&#39;s pull-request step unless one of them is a <code>feat:</code>, carries <code>!</code> or a <code>BREAKING CHANGE:</code> footer, or has a <code>Release-As:</code> footer. The release step always runs, so merging an existing release pull request still tags and publishes.</p><p>Once a release pull request is open (label <code>autorelease: pending</code>), the gate lets every later push through, so later fixes keep updating it, and they appear under <strong>Fixed</strong> in the changelog of that minor. To ship a fix on its own (a security or regression fix that cannot wait), run the workflow by hand with <code>force-release</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release-please.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> force-release=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>That opens a patch release pull request; merge it as usual. A <code>Release-As: X.Y.Z</code> footer on a commit does the same without the manual run.</p><h2 id="version-bumps" tabindex="-1">Version bumps <a class="header-anchor" href="#version-bumps" aria-label="Permalink to &quot;Version bumps&quot;">​</a></h2><p>release-please uses the <code>node</code> release type with <code>bump-minor-pre-major: false</code>, so semantic-versioning rules apply as written. Deciding which bump a change needs, and how to mark it, is in <a href="./semver">SEMVER.md</a>.</p><table tabindex="0"><thead><tr><th>Commit</th><th>Bump</th><th>Changelog section</th></tr></thead><tbody><tr><td><code>type!:</code> or a <code>BREAKING CHANGE:</code> footer, any type</td><td>major</td><td>as for the type</td></tr><tr><td><code>feat:</code></td><td>minor</td><td>Added</td></tr><tr><td><code>fix:</code></td><td>patch¹</td><td>Fixed</td></tr><tr><td><code>perf:</code>, <code>refactor:</code>, <code>chore:</code></td><td>patch¹</td><td>Changed</td></tr><tr><td><code>docs:</code></td><td>patch¹</td><td>Documentation</td></tr><tr><td><code>test:</code></td><td>patch¹</td><td>Testing</td></tr><tr><td><code>build:</code>, <code>ci:</code>, <code>style:</code>, <code>revert:</code> (allowed by commitlint)</td><td>none</td><td>not listed</td></tr></tbody></table><p>¹ Patch-level commits do not open a release on their own; they ride the next minor or major unless forced (see <a href="#release-cadence">Release cadence</a>).</p><p>The section mapping lives in <code>changelog-sections</code> in <code>release-please-config.json</code>. A type missing from that list is accepted by commitlint but does not appear in the changelog.</p><p>Two practical consequences:</p><ul><li><strong>Squash titles matter.</strong> A squash merge keeps only the pull request title as the commit, so the title carries the type and the <code>!</code>.</li><li><strong>Dropping a supported Node line is a major bump</strong> (REL-05). It needs a <code>!</code> and a changelog line, not a quiet edit to <code>engines</code>.</li><li><strong>A public API break must be declared.</strong> The <code>api-semver</code> job in <code>ci.yml</code> fails a pull request whose <code>etc/esi.ts.api.md</code> lost or changed a line unless one of its commits is <code>type!:</code> or has a <code>BREAKING CHANGE:</code> footer. If the change breaks no consumer, add an <code>API-Compatible: &lt;why&gt;</code> trailer instead. See GATE-03 in <a href="./quality-gates">QUALITY-GATES.md</a>. Squash merging is allowed: when a declared break spans several commits, the gate also requires the pull request title to be <code>type!:</code>, because that title becomes the squash commit. Edit the title and re-run the failed jobs; no new push is needed.</li></ul><hr><h2 id="the-changelog" tabindex="-1">The changelog <a class="header-anchor" href="#the-changelog" aria-label="Permalink to &quot;The changelog&quot;">​</a></h2><p><code>CHANGELOG.md</code> follows <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a> and Semantic Versioning.</p><ul><li>Work in progress is recorded under <code>## [Unreleased]</code> using the sections <code>Added</code>, <code>Changed</code>, <code>Deprecated</code>, <code>Removed</code>, <code>Fixed</code>, <code>Security</code>, and <code>Breaking Changes</code> where needed.</li><li>A release turns the unreleased block into <code>## [X.Y.Z] - YYYY-MM-DD</code>.</li><li><code>validate-release</code> fails if <code>CHANGELOG.md</code> has no heading starting <code>## [X.Y.Z]</code> for the version in <code>package.json</code>. Both the hand-written heading and release-please&#39;s linked heading satisfy that check.</li><li>Entries describe the consumer-visible change and name the public symbol, in the voice of the existing entries.</li><li>A change merged with a merge commit is listed once. GitHub&#39;s merge commit repeats the pull request&#39;s title in its body, and release-please reads that as a second commit, so such a change used to appear twice (<a href="https://github.com/lgriffin/ESI.ts/issues/377" target="_blank" rel="noreferrer">#377</a>). After release-please updates the release pull request, <code>release-please.yml</code> runs <code>npm run release:dedupe-changelog</code>. It drops a merge commit&#39;s line from the branch&#39;s <code>CHANGELOG.md</code> and from the pull request body (which becomes the GitHub release) only when a commit on the merged branch has exactly the same subject and that commit&#39;s own line, with its <code>closes</code> links, is in the same notes. A pull request title that summarises differently named commits keeps its line, and so does a merge whose branch commits release-please left out, so nothing that shipped disappears. Runs of the workflow take turns (<code>concurrency: release-please</code>), so two cannot rewrite the release pull request at once.</li></ul><h3 id="bumped-but-not-published-rel-04" tabindex="-1">Bumped but not published (REL-04) <a class="header-anchor" href="#bumped-but-not-published-rel-04" aria-label="Permalink to &quot;Bumped but not published (REL-04)&quot;">​</a></h3><p>If a version number is written to <code>package.json</code> and the changelog but the package is never published, the changelog <strong>records it as unreleased</strong> rather than letting the number disappear. Mark the heading, for example <code>## [9.8.0] - 2026-09-10 (not published)</code>, and fold its entries into the next published version&#39;s notes by reference.</p><p>The reverse also applies. If versions were published without a changelog entry, backfill the entry once from the tag&#39;s commit range (<code>git log vA..vB --oneline</code>) so a reader can see every number that exists on npm.</p><p>The changelog meets this rule from 7.4.0 through 9.9.0; see <a href="#known-state">Known state</a> for the numbers outside that range.</p><hr><h2 id="what-gates-a-publish-rel-02" tabindex="-1">What gates a publish (REL-02) <a class="header-anchor" href="#what-gates-a-publish-rel-02" aria-label="Permalink to &quot;What gates a publish (REL-02)&quot;">​</a></h2><p><code>validate-release</code> runs on Node 22 against the tagged commit. Every step blocks the publish.</p><table tabindex="0"><thead><tr><th>Step</th><th>Command</th><th style="text-align:center;">Blocks</th></tr></thead><tbody><tr><td>Tag matches version</td><td><code>package.json</code> version equals the tag, then <code>npm run validate:versions</code></td><td style="text-align:center;">●</td></tr><tr><td>Lint</td><td><code>npm run lint</code></td><td style="text-align:center;">●</td></tr><tr><td>Formatting</td><td><code>npm run format:check</code></td><td style="text-align:center;">●</td></tr><tr><td>Dead code</td><td><code>npx knip</code></td><td style="text-align:center;">●</td></tr><tr><td>Dependency audit</td><td><code>npm run audit:check</code> (allowlist with expiry, see SECURITY.md)</td><td style="text-align:center;">●</td></tr><tr><td>Changelog entry for version</td><td><code>grep &quot;## [X.Y.Z]&quot; CHANGELOG.md</code></td><td style="text-align:center;">●</td></tr><tr><td>Build</td><td><code>npm run build</code></td><td style="text-align:center;">●</td></tr><tr><td>Schema drift</td><td><code>npm run schema:drift:ci</code></td><td style="text-align:center;">●</td></tr><tr><td>Generated types fresh</td><td><code>npm run generate:types</code>, then <code>git diff --exit-code</code> on <code>src/types/generated/</code> and <code>src/core/endpoints/esi-*.generated.ts</code></td><td style="text-align:center;">●</td></tr><tr><td>Generated operations fresh</td><td><code>npm run spec:generate:check</code></td><td style="text-align:center;">●</td></tr><tr><td>Auth/scope alignment</td><td><code>npm run validate:auth-scopes</code> (DES-04, both directions)</td><td style="text-align:center;">●</td></tr><tr><td>Endpoint definitions</td><td><code>npm run validate:esi</code> (ARCH-02)</td><td style="text-align:center;">●</td></tr><tr><td>EARS spec audit</td><td><code>npm run spec:audit</code>, then <code>npm run validate:spec-consistency</code></td><td style="text-align:center;">●</td></tr><tr><td>Test suite</td><td><code>npm run test:all</code> (unit + BDD, BDD, integration, fuzz, tsd)</td><td style="text-align:center;">●</td></tr><tr><td>Recorded payload replay</td><td><code>npm run contract:replay</code></td><td style="text-align:center;">●</td></tr><tr><td>Fault catalogue</td><td><code>npm run faults -- --ci</code></td><td style="text-align:center;">●</td></tr><tr><td>Live contract tests</td><td><code>npm run contract:live</code>; a 503 from ESI is a warning, as on pull requests</td><td style="text-align:center;">●</td></tr><tr><td>API reference builds</td><td><code>npm run docs</code></td><td style="text-align:center;">●</td></tr></tbody></table><p>The shrink-only ratchets in <code>spec:audit</code>, <code>contract:replay</code> and the fault catalogue compare with the previous release tag (<code>SPEC_AUDIT_BASE_REF</code>, <code>CONTRACT_BASE_REF</code> and <code>FAULTS_BASE_REF</code> set to <code>git describe --tags --abbrev=0 HEAD^</code>, on a checkout with full history and tags), so an exception added since the last release fails the release, and a master that has since shrunk a list cannot block releasing an earlier commit. With no earlier tag the job fails rather than falling back to <code>origin/master</code>. Schema drift still uses the tag itself as its base. Not in the release gate, although they gate pull requests: the API surface diff and the SemVer gate, which need a base branch, and the consumer contract, which <code>release.yml</code> runs as its own job on the packed tarball.</p><p>Run the same checks locally before tagging:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:all</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # lint, format, build, coverage, knip, validate:esi, validate:spec, validate:versions, spec:audit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema:drift:ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:all</span></span></code></pre></div><hr><h3 id="one-tarball-everywhere" tabindex="-1">One tarball, everywhere <a class="header-anchor" href="#one-tarball-everywhere" aria-label="Permalink to &quot;One tarball, everywhere&quot;">​</a></h3><p><code>create-assets</code> runs <code>npm pack</code> once. That tarball is what the consumer matrix installs, what cosign signs, what goes on the GitHub Release, and — since <code>esi-23g.42</code> — what both <code>publish-npm</code> and <code>publish-github</code> upload, rather than each rebuilding from a fresh checkout.</p><p>Both publish jobs re-verify <code>checksums.txt</code> before uploading. If the bytes changed between packing and publishing, the artefact cosign signed and the artefact npm serves are already different, and the run stops rather than shipping the discrepancy.</p><p>That is what makes the canary&#39;s <code>signatures</code> check meaningful: the provenance attestation, the cosign bundle and the npm tarball all describe the same bytes.</p><h2 id="what-is-published-where" tabindex="-1">What is published where <a class="header-anchor" href="#what-is-published-where" aria-label="Permalink to &quot;What is published where&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Destination</th><th>Artefact</th><th>Integrity</th></tr></thead><tbody><tr><td>npm registry (<code>registry.npmjs.org</code>)</td><td><code>@lgriffin/esi.ts</code> tarball, <code>dist/</code> + README, LICENSE, CHANGELOG</td><td>npm provenance (SLSA v1 attestation)</td></tr><tr><td>GitHub Packages (<code>npm.pkg.github.com</code>)</td><td>Same package</td><td>Published with <code>--provenance</code></td></tr><tr><td>GitHub release assets</td><td><code>lgriffin-esi.ts-X.Y.Z.tgz</code>, <code>lgriffin-esi.ts-X.Y.Z.cdx.json</code> (SBOM), <code>docs.tar.gz</code>, <code>README.md</code>, <code>LICENSE</code></td><td><code>checksums.txt</code> (SHA-256); a <code>.sigstore.json</code> bundle per archive and SBOM from keyless cosign; <code>lgriffin-esi.ts-X.Y.Z.intoto.jsonl</code>, the SLSA provenance for all three</td></tr><tr><td>GitHub Pages</td><td>The documentation site, with the TypeDoc API reference under <code>/api/</code></td><td>—</td></tr></tbody></table><p>The published file list is the <code>files</code> field in <code>package.json</code>. <code>publishConfig.access</code> is <code>public</code>.</p><h3 id="the-post-publish-canary-tier-p" tabindex="-1">The post-publish canary (tier P) <a class="header-anchor" href="#the-post-publish-canary-tier-p" aria-label="Permalink to &quot;The post-publish canary (tier P)&quot;">​</a></h3><p>Everything above the publish step checks what CI built. <code>post-publish-canary.yml</code> checks what the registry serves, which is not always the same artefact: <code>publish-npm</code> uploads the tarball the consumer matrix tested, but the registry can still serve something else, and a broken <code>exports</code> map is invisible until somebody installs it.</p><p><code>release.yml</code> dispatches it once <code>publish-npm</code> has succeeded and the assets job has finished. It installs the version into an empty directory with nothing from this repository on disk, and establishes four things:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Check</th><th style="text-align:left;">What it proves</th></tr></thead><tbody><tr><td style="text-align:left;"><code>registry</code></td><td style="text-align:left;">npm serves that exact version, and its tarball resolves</td></tr><tr><td style="text-align:left;"><code>signatures</code></td><td style="text-align:left;"><code>npm audit signatures</code> verifies the registry signature and the provenance attestation</td></tr><tr><td style="text-align:left;"><code>subpaths</code></td><td style="text-align:left;">every documented sub-path loads under both <code>require</code> and <code>import</code></td></tr><tr><td style="text-align:left;"><code>live</code></td><td style="text-align:left;">one real call to public ESI returns data</td></tr></tbody></table><p>A check that did not report, or was skipped, counts as a failure — &quot;we did not look&quot; must not read the same as &quot;we looked and it was fine&quot;. A failure opens one issue per version, labelled <code>release-verification</code>, and re-running comments on it rather than opening another.</p><p>Run it by hand against any published version:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release:canary</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.0.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # from a checkout</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> post-publish-canary.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10.0.0</span></span></code></pre></div><p>Its own signal is a version that predates a sub-path. <code>9.0.0</code> has no <code>./sde</code>, so the canary fails on it with <code>ERR_PACKAGE_PATH_NOT_EXPORTED</code>, which is the shape a broken <code>exports</code> map takes; <code>10.0.0</code> verifies all four checks. That is the fire drill the plan asked for, without publishing a deliberately broken pre-release.</p><h3 id="if-the-canary-fails-deprecate-and-fix-forward" tabindex="-1">If the canary fails: deprecate and fix forward <a class="header-anchor" href="#if-the-canary-fails-deprecate-and-fix-forward" aria-label="Permalink to &quot;If the canary fails: deprecate and fix forward&quot;">​</a></h3><p>A published version cannot be replaced or re-uploaded. npm allows <code>unpublish</code> only within 72 hours and only when nothing depends on it, and using it breaks anyone who already installed. So:</p><ol><li><p><strong>Deprecate it,</strong> naming the problem and the version to use instead. The version stays installable for anyone already pinned to it, and everybody else gets a warning on install:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deprecate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@lgriffin/esi.ts@X.Y.Z&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Broken exports map; use X.Y.Z+1&#39;</span></span></code></pre></div></li><li><p><strong>Fix forward.</strong> A patch release, or a major if the fix changes the public contract — the fact that the broken version shipped does not change how <code>guides/SEMVER.md</code> classifies the fix.</p></li><li><p><strong>Re-run the canary</strong> against the new version and close the <code>release-verification</code> issue with the passing run linked.</p></li><li><p><strong>Write down what the gates missed</strong> as an issue against the runway epic. A canary failure means every tier before it passed on something consumers could not use, and that gap is the more useful finding.</p></li></ol><hr><h3 id="verifying-a-release" tabindex="-1">Verifying a release <a class="header-anchor" href="#verifying-a-release" aria-label="Permalink to &quot;Verifying a release&quot;">​</a></h3><p><strong>npm provenance.</strong> In a project that depends on the package:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> signatures</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @lgriffin/esi.ts@X.Y.Z</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist.attestations</span></span></code></pre></div><p>The attestation links the tarball to the <code>release.yml</code> run and commit that built it.</p><p><strong>Checksums.</strong> Download the assets from the GitHub release, then:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checksums.txt</span></span></code></pre></div><p><strong>cosign signatures.</strong> Signing is keyless, so the identity to check is the workflow, not a key:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cosign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify-blob</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lgriffin-esi.ts-X.Y.Z.tgz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lgriffin-esi.ts-X.Y.Z.tgz.sigstore.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --certificate-identity</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://github.com/lgriffin/ESI.ts/.github/workflows/release.yml@refs/tags/vX.Y.Z&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --certificate-oidc-issuer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://token.actions.githubusercontent.com</span></span></code></pre></div><p>Releases from 10.0.0 on carry a Sigstore bundle (<code>.sigstore.json</code>) per asset. Earlier releases carried a separate <code>.sig</code> and <code>.pem</code>, verified with <code>--signature</code> and <code>--certificate</code> instead of <code>--bundle</code>.</p><p>Repeat with <code>docs.tar.gz</code> for the documentation archive.</p><p><strong>Build provenance.</strong> From the first release after this change, each release carries <code>lgriffin-esi.ts-X.Y.Z.intoto.jsonl</code>: one SLSA provenance attestation naming the tarball, the SBOM and <code>docs.tar.gz</code> by SHA-256, signed through Sigstore by <code>release.yml</code> and also recorded on the repository. With the GitHub CLI, either form verifies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attestation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lgriffin-esi.ts-X.Y.Z.tgz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lgriffin/ESI.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attestation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lgriffin-esi.ts-X.Y.Z.tgz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lgriffin/ESI.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lgriffin-esi.ts-X.Y.Z.intoto.jsonl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --signer-workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lgriffin/ESI.ts/.github/workflows/release.yml</span></span></code></pre></div><p><code>sign-and-publish-assets</code> runs the second command on all three assets before it uploads anything, so a release never carries a provenance file that does not verify. The file is also what OpenSSF Scorecard&#39;s Signed-Releases check looks for.</p><p><strong>SBOM (SEC-06).</strong> From the first release after this change, each release carries <code>lgriffin-esi.ts-X.Y.Z.cdx.json</code>, a CycloneDX 1.5 JSON bill of materials for that tarball, listed in <code>checksums.txt</code> and signed like the tarball:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cosign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify-blob</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lgriffin-esi.ts-X.Y.Z.cdx.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lgriffin-esi.ts-X.Y.Z.cdx.json.sigstore.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --certificate-identity</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://github.com/lgriffin/ESI.ts/.github/workflows/release.yml@refs/tags/vX.Y.Z&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --certificate-oidc-issuer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://token.actions.githubusercontent.com</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.metadata.component.purl, (.components[] | &quot;\\(.name)@\\(.version)&quot;)&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lgriffin-esi.ts-X.Y.Z.cdx.json</span></span></code></pre></div><p>What it describes: the runtime dependency tree of the tarball&#39;s own <code>package.json</code> (<code>dependencies</code> and everything they pull in), at the versions in this repository&#39;s <code>package-lock.json</code> — the ones the release was tested with. A consumer&#39;s install resolves the same ranges and can pick newer patches, so the SBOM states what was shipped and tested, not what every install will contain. Dev dependencies are not in it, and neither are the optional peers (<code>better-sqlite3</code>, <code>js-yaml</code>, <code>adm-zip</code>), which a default install does not fetch. The build bundles no third-party package, so the dependency tree is the whole inventory.</p><p><code>npm run release:sbom -- --tarball &lt;file&gt;</code> generates it. <code>scripts/release/release-sbom-core.ts</code> fails the release if the document is not CycloneDX, does not name <code>@lgriffin/esi.ts</code> at the tagged version with its purl, or leaves out a runtime dependency, and explains why it does not use <code>npm sbom --omit dev</code> on the checkout (that drops <code>zod</code> and part of pino&#39;s tree, because dev tools share them). <code>tests/tdd/release-sbom/</code> runs the generator against the repository on every <code>npm test</code>.</p><hr><h2 id="version-strings-rel-03" tabindex="-1">Version strings (REL-03) <a class="header-anchor" href="#version-strings-rel-03" aria-label="Permalink to &quot;Version strings (REL-03)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Location</th><th>Written by</th><th>Checked by</th></tr></thead><tbody><tr><td><code>package.json</code></td><td>release-please</td><td><code>npm run validate:versions</code></td></tr><tr><td><code>package-lock.json</code></td><td>release-please (node release type)</td><td><code>npm ci</code> in CI</td></tr><tr><td><code>.release-please-manifest.json</code></td><td>release-please</td><td>—</td></tr><tr><td><code>src/core/constants.ts</code> (<code>PACKAGE_VERSION</code>, sent in the User-Agent)</td><td>release-please <code>extra-files</code></td><td><code>npm run validate:versions</code></td></tr><tr><td>README release line (<code>metric:version</code>)</td><td>release-please <code>extra-files</code></td><td><code>npm run validate:versions</code></td></tr><tr><td><code>etc/doc-metrics.json</code> (<code>version</code>)</td><td>release-please <code>extra-files</code></td><td><code>npm run validate:versions</code></td></tr><tr><td>docs-site version menu</td><td>read from <code>package.json</code> at build</td><td><code>npm run validate:versions -- --site</code></td></tr></tbody></table><p><code>scripts/package/validate-versions.ts</code> compares <code>package.json</code> with <code>PACKAGE_VERSION</code>, checks that the docs-site selector is still read from <code>package.json</code>, and with <code>--site</code> checks the built site; it exits non-zero on a mismatch. It runs in <code>ci.yml</code> <code>static-analysis</code>, <code>release.yml</code> <code>validate-release</code> and <code>npm run check:all</code>, and with <code>--site</code> in the <code>documentation</code> job and <code>docs-site.yml</code>. It also runs the <code>DOC-04</code> metrics check, which compares the README&#39;s release line and every other marked count with <code>etc/doc-metrics.json</code> and the source.</p><hr><h2 id="support-window" tabindex="-1">Support window <a class="header-anchor" href="#support-window" aria-label="Permalink to &quot;Support window&quot;">​</a></h2><p>The supported major versions are listed once, in the root <a href="https://github.com/lgriffin/ESI.ts/blob/master/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>. Update that table in the same pull request as a major release.</p><p>The package declares <code>&quot;engines&quot;: { &quot;node&quot;: &quot;&gt;=22.12.0&quot; }</code> (REL-05) and supports TypeScript 5.4 or later for consumers (<code>OLDEST_TYPESCRIPT</code> in <code>scripts/quality/consumer-contract-core.ts</code>; zod 4&#39;s declarations need <code>NoInfer</code>, added in 5.4). The consumer contract checks both floors on every pull request and release: its oldest-TypeScript row runs on Node 22.12 exactly, since a bare <code>22</code> would install the newest 22.x. Pull requests run unit tests on Node 22 and 24. Release jobs and the rest of CI run on Node 22, which is also the version in <code>.nvmrc</code>. Node 22 is the floor from 11.0.0 because Node 18 and 20 are end of life, and 22.12 within it because it is the first 22.x to load an ES module through <code>require()</code> without a flag; 10.x is the line for Node 18 and 20.</p><hr><h2 id="known-state" tabindex="-1">Known state <a class="header-anchor" href="#known-state" aria-label="Permalink to &quot;Known state&quot;">​</a></h2><p>Recorded 2026-09-16. Each item contradicts a requirement above and belongs in a bead, not a softened sentence.</p><ul><li><strong>npm publishing still uses a long-lived token.</strong> Both publish jobs now upload the tarball <code>create-assets</code> packed and cosign signed (<code>esi-23g.42</code>), so the registries and the GitHub Release carry the same bytes. <code>publish-npm</code> still authenticates with the <code>NPM_TOKEN</code> secret; moving it to npm trusted publishing needs the maintainer to configure the trusted publisher on npmjs.com first (<a href="./security#5-settings-only-the-maintainer-can-change">SECURITY.md</a>, ROADMAP Phase 6 item 3).</li><li><strong>Recent GitHub releases are missing their signed assets.</strong> v10.2.0 carries the tarball, SBOM, docs archive, their cosign bundles and <code>checksums.txt</code>; v10.2.2 and v10.2.3 carry no assets at all (checked 2026-09-27), so <code>sign-and-publish-assets</code> did not run or did not finish for them. OpenSSF Scorecard&#39;s Signed-Releases check reads the last five releases, so it stays low until the releases in that window are signed; no release before this change has a <code>.intoto.jsonl</code>.</li><li><strong>release-please needed repository permission to open its pull request.</strong> It computed the version but failed with &quot;GitHub Actions is not permitted to create or approve pull requests&quot; until that repository setting was enabled (2026-09-16). Releases 9.8.0 and 9.9.0 were hand-written <code>chore: release X.Y.Z</code> commits.</li><li><strong>Releases created with the workflow&#39;s <code>GITHUB_TOKEN</code> do not trigger other workflows.</strong> 10.1.0 and 10.1.1 were tagged and released on GitHub but never published to npm, because nothing dispatched <code>release.yml</code>. <code>release-please.yml</code> now uses the <a href="#the-release-app-token">release app token</a> when it is configured, and dispatches <code>release.yml</code> and the canary itself when it is not.</li><li><strong>v9.7.0 has no signed assets.</strong> Its <code>sign-and-publish-assets</code> job failed because cosign 3 requires <code>--bundle</code> for <code>sign-blob</code>; the job now writes a Sigstore bundle per asset. npm and GitHub Packages publishing succeeded for that release.</li><li><strong>The changelog does not yet mark every unpublished number (REL-04).</strong> Every number written to <code>package.json</code> from 7.4.0 through 9.9.0 now has an entry: 8.0.0, 9.4.0 and 9.6.0 were backfilled from their tag ranges, and 9.1.1 to 9.2.0, 9.5.0 to 9.5.2, 9.6.1, 9.6.2, 9.8.0, 9.8.1 and 9.9.0 are headed <code>(not published)</code> with the release their changes shipped in (<a href="https://github.com/lgriffin/ESI.ts/issues/275" target="_blank" rel="noreferrer">#275</a>). Outside that range, 7.0.0 to 7.3.0 and earlier numbers missing from npm, and 10.1.0, 10.1.1, 10.2.2 and 10.2.3 (tagged, not on npm, checked 2026-09-27), still have ordinary headings.</li></ul>`,95)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
